#!/usr/bin/env node
// Bake the LIVE TITLE replay tape (build_map.md §25 Phase 5.2).
//
// Runs the deterministic attract world (src/sim/titleAttract.js) at the fixed title
// seed, records every ship life / shot / guided round through src/sim/titleAttractTape.js,
// and writes the packed tape as a generated module:
//
//   src/sim/titleAttractTapeData.js   (GENERATED — do not edit by hand)
//
// Re-run after any change that can move the fight: the roster, the seed, enemy or
// weapon data, ai/flight/weapons/physics/combat. test/title-attract.test.mjs compares
// a fresh bake to the committed module, so a stale tape fails loudly, not silently.
//
//   node scripts/bake-title-attract.mjs [--ticks=3600] [--warmup=0] [--out=path]

import { writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, resolve } from 'node:path';
import { createTitleAttractWorld, TITLE_ATTRACT_SEED } from '../src/sim/titleAttract.js';
import {
  createTapeRecorder,
  encodeTape,
  hashEncodedTape,
  TAPE_DURATION_TICKS,
} from '../src/sim/titleAttractTape.js';

const here = dirname(fileURLToPath(import.meta.url));
const arg = (name, fallback) => {
  const hit = process.argv.find((a) => a.startsWith(`--${name}=`));
  return hit ? hit.slice(name.length + 3) : fallback;
};
const TICKS = Math.max(60, Number(arg('ticks', TAPE_DURATION_TICKS)) | 0);
const WARMUP = Math.max(0, Number(arg('warmup', 0)) | 0);
const OUT = resolve(here, '..', String(arg('out', 'src/sim/titleAttractTapeData.js')));

const world = createTitleAttractWorld({ seed: TITLE_ATTRACT_SEED });
world.start();
if (WARMUP > 0) world.runTicks(WARMUP);

const recorder = createTapeRecorder({ ticks: TICKS, seed: TITLE_ATTRACT_SEED });
const t0 = Date.now();
let keepGoing = true;
while (keepGoing) {
  world.runTicks(1);
  keepGoing = recorder.tick(world.state);
}
const tape = recorder.finish(world.state);
const counts = world.counts();
world.dispose();

const encoded = encodeTape(tape);
const hash = hashEncodedTape(encoded);
const binBytes = Math.floor(encoded.bin.length * 0.75);
console.log(`[bake-title-attract] ${TICKS} ticks in ${Date.now() - t0} ms — ` +
  `${encoded.ships.length} ship lives, ${encoded.shots.count} shots, ` +
  `${encoded.guided.length} guided, bin ${binBytes} B, hash ${hash}`);
console.log(`[bake-title-attract] world evidence:`, JSON.stringify(counts));

const source = `// GENERATED by scripts/bake-title-attract.mjs — do not edit by hand.
// Deterministic Crucible replay for the live title (build_map.md §25 Phase 5.2).
// Re-bake after any change that can move the fight; test/title-attract.test.mjs
// compares a fresh bake to this module's bytes.
// seed=${encoded.seed} ticks=${encoded.ticks} hash=${hash}
export const TITLE_ATTRACT_TAPE = ${JSON.stringify(encoded)};
`;
writeFileSync(OUT, source);
console.log(`[bake-title-attract] wrote ${OUT} (${source.length} B)`);
